<section class="page-wrap admin-wrap"><div class="admin-head"><div><span class="section-kicker">Bibliothèque</span><h1>Contenus & lives</h1><p>Publiez un conseil, programmez un live ou archivez un replay.</p></div></div><div class="admin-columns content-admin"><section class="panel"><div class="panel-head"><div><span class="section-kicker">Nouveau</span><h2>Ajouter un contenu</h2></div></div><form class="admin-form" method="post" action="/admin/conseils"><label>Titre<input name="title" required placeholder="Ex. Le rituel du soir"></label><label>Accroche<input name="excerpt" required placeholder="Une phrase pour donner envie"></label><label>Texte<textarea name="body" required rows="4" placeholder="Votre contenu..."></textarea></label><label>Image (URL)<input name="image" placeholder="https://..."></label><label>Vidéo YouTube (URL)<input name="video_url" placeholder="https://youtube.com/watch?v=..."></label><label>Type<select name="type"><option value="conseil">Conseil</option><option value="live">Live à venir</option><option value="archive">Archive vidéo</option></select></label><button class="button button-dark" type="submit">Publier <span>→</span></button></form></section><section class="panel"><div class="panel-head"><div><span class="section-kicker">En ligne</span><h2>Vos contenus</h2></div></div><?php foreach ($contents as $item): ?><div class="mini-row"><div><b><?= htmlspecialchars($item['title']) ?></b><small><?= ucfirst($item['type']) ?> · <?= date('d.m.Y', strtotime($item['created_at'])) ?></small></div><span class="status <?= $item['type'] === 'live' ? 'status-live' : '' ?>"><?= $item['type'] === 'live' ? 'Live' : 'Publié' ?></span></div><?php endforeach; ?></section></div></section>
